// AccountUpdate A user may not set or change device_code: the device code is the
// platform device identity, and a user can only obtain it through
// device-refresh. A user update carrying any device_code, including an
// empty string, answers 403. phone_model is not a device identity, but
// a model edit still counts as a credential edit (a rejected account
// resubmits and a credential_error account recovers), and every role
// may write it.
// current_password is the acting user's own login password, never the
// account credential. The server requires it when the request carries
// phone, password or device_code and answers 400 when it is missing,
// 403 when it is wrong and 429 after repeated failures.
type AccountUpdate struct {
	// CurrentPassword The acting user's own login password, used to re-authenticate a
	// dangerous operation. It is never the signing account's platform
	// credential, and it is never stored, logged or audited. Optional in
	// this schema; the server requires it on the dangerous endpoints and
	// answers 400 when it is missing, 403 when it is wrong and 429 after
	// repeated failures.
	CurrentPassword *CurrentPassword `json:"current_password,omitempty"`

	// DeviceCode master and admin may set or clear it: an empty string clears the
	// stored device code. A user update carrying any device_code,
	// including an empty string, answers 403.
	DeviceCode *string `json:"device_code,omitempty"`

	// ExpectedUpdatedAt Optimistic-lock precondition. Send back the raw updated_at string
	// from the most recent Account response, byte for byte. Do not pass
	// it through a JavaScript Date or toISOString(): those keep only
	// milliseconds, drop the microsecond digits PostgreSQL stores, and
	// make every update answer 409. When the value differs from the
	// current row the update answers 409 conflict and writes nothing: no
	// account field, credential or audit row. Omitting it keeps the
	// legacy last-write-wins behavior for older clients; new clients
	// should always send it.
	ExpectedUpdatedAt *time.Time `json:"expected_updated_at,omitempty"`

	// Name Remark name; trimmed. An empty string clears it. A name-only edit
	// keeps the status, including rejected.
	Name     *string `json:"name,omitempty"`
	Password *string `json:"password,omitempty"`

	// Phone A new phone returns a non-pending account to pending: the review
	// decision binds to the old phone. An unchanged phone is not a
	// rebind and keeps the status. On a rejected account only a
	// credential edit (a new phone, password, device code or model)
	// resubmits; a name-only edit or an unchanged phone does not.
	Phone      *string `json:"phone,omitempty"`
	PhoneModel *string `json:"phone_model,omitempty"`

	// SchoolId A different value returns 409 conflict. Changing school is
	// forbidden in P1 (decision 12.3).
	SchoolId *string `json:"school_id,omitempty"`
}

